{
  "name": "open-guardian",
  "version": "0.2.2",
  "description": "LLM permission judge for OpenCode. Codex-Guardian-style auto-approval: an ordered-rules floor plus a model that scores risk and user authorization for every escalated action.",
  "type": "module",
  "exports": {
    ".": "./index.ts"
  },
  "files": [
    "index.ts",
    "policy.md"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "permissions",
    "guardian",
    "auto-approval",
    "agent-safety"
  ],
  "author": "Afif",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/opzero1/open-guardian.git"
  },
  "homepage": "https://github.com/opzero1/open-guardian#readme",
  "bugs": {
    "url": "https://github.com/opzero1/open-guardian/issues"
  },
  "scripts": {
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@opencode/plugin": "2.0.3"
  },
  "devDependencies": {
    "@types/node": "^24.0.0",
    "typescript": "5.9.3"
  }
}
